/**
 *
 * DataTableCellEditor provides inline cell editing functionality inside a DataTable Cell.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableCellEditor
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseDataTableCellEditEvent } from '@primereact/types/headless/datatable';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableCellEditor component.
 */
export type DataTableCellEditorPassThroughType<E> = PassThroughType<DataTableCellEditorInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableCellEditor component.
 */
export interface DataTableCellEditorPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableCellEditorPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in DataTableCellEditor component.
 */
export interface DataTableCellEditorProps extends BaseComponentProps<DataTableCellEditorInstance, unknown, DataTableCellEditorPassThrough, 'div'> {
    /**
     * Field name associated with this cell.
     */
    field: string;
    /**
     * Row index of this cell.
     */
    rowIndex: number;
    /**
     * Row data associated with this cell.
     */
    rowData?: Record<string, unknown>;
    /**
     * CellEditorDisplay and CellEditorContent sub-components.
     */
    children?: React.ReactNode;
}
/**
 * Defines valid state in DataTableCellEditor component.
 */
export interface DataTableCellEditorState {
    /**
     * Whether the cell is in edit mode.
     */
    isEditing: boolean;
}
/**
 * Defines the methods and properties exposed by DataTableCellEditor component.
 */
export interface DataTableCellEditorExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableCellEditor component.
 */
export type DataTableCellEditorInstance = ComponentInstance<DataTableCellEditorProps, DataTableCellEditorState, DataTableCellEditorExposes>;
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseDataTableCellEditEvent`.
 */
export interface DataTableCellEditEvent extends UseDataTableCellEditEvent {
}
